export const createValidExcessivePixelPng = (): Promise<Buffer> =>
  sharp({
    create: {
      width: 5_001,
      height: 5_000,
      channels: 3,
      background: { r: 1, g: 2, b: 3 }
    }
  })
    .png({ compressionLevel: 9, palette: true })
    .toBuffer();
